      {
        "type": "input-text",
        "name": "username",
        "label": "用户名",
        "placeholder": "请输入用户名",
        "required": true
      },
      {
        "type": "input-password",
        "name": "password",
        "label": "密码",
        "placeholder": "请输入密码",
        "required": true
