{
  "type": "page",
  "title": "动态表单示例",
  "body": {
    "type": "form",
    "api": "POST:/api/dynamic-form",
    "body": [
      {
        "type": "select",
        "name": "occupation",
        "label": "您的职业类型",
        "required": true,
        "options": [
          { "label": "学生", "value": "student" },
          { "label": "上班族", "value": "office-worker" },
          { "label": "自由职业者", "value": "freelancer" }
        ],
        "onChange": "this.setValues({ 'nextQuestion': '' });"
      },
      {
        "type": "div",
        "name": "dynamic-question",
        "visibleOn": "this.occupation",
        "body": {
          "type": "form",
          "body": [
            {
              "type": "select",
              "name": "nextQuestion",
              "label": "请选择您关心的问题",
              "visibleOn": "this.occupation === 'student'",
              "options": [
                { "label": "学习科目", "value": "study-subject" },
                { "label": "考试时间", "value": "exam-time" },
                { "label": "课外活动", "value": "extracurricular" }
              ]
            },
            {
              "type": "select",
              "name": "nextQuestion",
              "label": "请选择您关心的问题",
              "visibleOn": "this.occupation === 'office-worker'",
              "options": [
                { "label": "工作内容", "value": "work-content" },
                { "label": "加班情况", "value": "overtime" },
                { "label": "职业发展", "value": "career-growth" }
              ]
            },
            {
              "type": "select",
              "name": "nextQuestion",
              "label": "请选择您关心的问题",
              "visibleOn": "this.occupation === 'freelancer'",
              "options": [
                { "label": "项目类型", "value": "project-type" },
                { "label": "收入来源", "value": "income-source" },
                { "label": "时间管理", "value": "time-management" }
              ]
            }
          ]
        }
      },
      {
        "type": "submit",
        "label": "提交"
      }
    ]
  }
}

